/*
 * Free an nsproxy that was never activated (i.e., nsproxy_ns_active_get was never called).
 * This does NOT decrement the active reference count of namespaces.
 */
static void free_inactive_nsproxy(struct nsproxy *ns)
{
	put_mnt_ns(ns->mnt_ns);
	put_uts_ns(ns->uts_ns);
	put_ipc_ns(ns->ipc_ns);
	put_pid_ns(ns->pid_ns_for_children);
	put_time_ns(ns->time_ns);
	put_time_ns(ns->time_ns_for_children);
	put_cgroup_ns(ns->cgroup_ns);
	put_net(ns->net_ns);
	kmem_cache_free(nsproxy_cachep, ns);
}

/*
 * Free an nsproxy that was in active use (i.e., installed in a task's nsproxy).
 * This decrements the active reference count of all namespaces before freeing.
 */
void free_nsproxy(struct nsproxy *ns)
{
	nsproxy_ns_active_put(ns);
	free_inactive_nsproxy(ns);
}
